def count_valid_multiples(X, A, B, allowed_digits):
    count = 0
    allowed_set = set(allowed_digits)

    def is_valid(num):
        return all(d in allowed_set for d in str(num))

    current = (A + X - 1) // X * X
    while current <= B:
        if is_valid(current):
            count += 1
        current += X

    return count

